var n=`0525-kashk-e-bademjan`;var t=`world-0525`;var a=`IR`;var s=`western-asia`;var o=4;var r=58;var g={en:`Kashk-e Bademjan`,ua:`Кашк-е бадемджан`};var l={en:`A traditional dish from Iran, centered on eggplant, yellow onion, garlic, mint. A measured home-kitchen version organized by cooking step. Uses a yogurt–tahini dressing instead of traditional Iranian kashk, which is absent from the catalog.`,ua:`Традиційна страва кухні країни Іран. Основні складники: баклажан, жовта цибуля, часник, м'ята. Домашній варіант із кількостями продуктів за етапами приготування. Замість традиційного іранського кашку використано йогуртово-тахінну заправку.`};var d=[{en:`Cut the vegetables evenly and roast at 200°C for about 35 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 35 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:35,i:[[`eggplant`,750,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,260,`g`],[`garlic`,5,`clove`],[`extra-virgin-olive-oil`,70,`ml`],[`mint`,12,`g`]]},{en:`Fold in the creamy yogurt and tahini mixture as a substitute for kashk, leaving some for garnish.`,ua:`Вмішайте вершкову суміш із йогурту й тахіні замість кашку; частину залиште для прикрашання.`,t:[`mixing`],m:8,i:[[`greek-yogurt`,240,`g`],[`tahini`,50,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`walnut`,70,`g`]]}];var h={slug:n,id:t,country:`IR`,region:s,servings:4,minutes:58,title:g,text:l,steps:d};export{a as country,h as default,t as id,r as minutes,s as region,o as servings,n as slug,d as steps,l as text,g as title};